    return Pipeline([
        ("prep", _preprocessor(profile, impute='median', scale='none', cat='onehot', fe=())),
        ("model", RandomForestClassifier(n_estimators=300, min_samples_leaf=1, max_features='sqrt', max_depth=None, random_state=0)),
